import{_ as i,C as n,o as t,c as s,a2 as a,b as l,w as o,a as c,E as d,a3 as h}from"./chunks/framework.DW4RdtHL.js";const p="/github-pages-docs/vitepress/console-mockup.png",v=JSON.parse('{"title":"Rotate API Gateway Database Credentials","description":"","frontmatter":{},"headers":[],"relativePath":"sops/rotate-credentials.md","filePath":"sops/rotate-credentials.md","lastUpdated":null}'),u={name:"sops/rotate-credentials.md"};function g(m,e,f,w,b,y){const r=n("Mermaid");return t(),s("div",null,[e[1]||(e[1]=a('<h1 id="rotate-api-gateway-database-credentials" tabindex="-1">Rotate API Gateway Database Credentials <a class="header-anchor" href="#rotate-api-gateway-database-credentials" aria-label="Permalink to &quot;Rotate API Gateway Database Credentials&quot;">​</a></h1><p><strong>Status:</strong> Active · <strong>Owner:</strong> Platform Team · <strong>Last updated:</strong> 2026-09-01</p><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>The API gateway authenticates every storefront request against a small backing PostgreSQL database that stores API keys and client credentials. The gateway&#39;s database credential is rotated quarterly and immediately on any suspected compromise. This SOP describes how to rotate that credential without dropping authenticated traffic.</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><ul><li><strong>In scope:</strong> the credential the API gateway uses to connect to its auth database (<code>gateway-auth-db</code>), and the gateway replicas that consume it.</li><li><strong>Out of scope:</strong> the order service&#39;s database credential (<code>orders-db</code>), the Redis session store, and the message queue. Each of those has its own rotation cadence and SOP.</li></ul><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>You have <code>rotate</code> permission on the <code>gateway-auth-db</code> credential in the secret manager.</li><li>You can access the Acme Cloud console and the gateway&#39;s rollout controls.</li><li>The rotation window is confirmed on the on-call calendar.</li></ul><p>Before you start, complete the pre-flight checklist:</p><ul><li>[ ] Confirm no deployment is in flight on the gateway</li><li>[ ] Verify the secret manager is reachable from the gateway network</li><li>[ ] Snapshot the current gateway config for rollback reference</li><li>[ ] Check the gateway error rate is at baseline (no open incidents)</li><li>[ ] Announce the rotation window in the #ops channel</li></ul><p>You will monitor the gateway from the console during the rotation:</p><p><img src="'+p+'" alt="Acme Cloud console, Services page"></p><p><em>Figure 1: The Acme Cloud console Services page. The <code>order-service-api</code> row is the API gateway; its status must remain <strong>Running</strong> throughout the rotation.</em></p><h2 id="decision-path" tabindex="-1">Decision path <a class="header-anchor" href="#decision-path" aria-label="Permalink to &quot;Decision path&quot;">​</a></h2><p>A scheduled rotation and a compromise-driven rotation diverge at the first step: a compromise revokes the old credential before a replacement is deployed, which means a brief window where the gateway cannot reach its auth database.</p>',15)),(t(),l(h,null,{default:o(()=>[d(r,{id:"mermaid-92",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5BRotation%20requested%5D%20--%3E%20B%7BReason%3F%7D%0A%20%20%20%20B%20--%3E%7CScheduled%20%2F%20expired%7C%20C%5BRun%20pre-flight%20checklist%5D%0A%20%20%20%20B%20--%3E%7CSuspected%20compromise%7C%20D%5BRevoke%20compromised%20credential%20immediately%5D%0A%20%20%20%20D%20--%3E%20E%5BCreate%20replacement%20credential%20in%20secret%20manager%5D%0A%20%20%20%20E%20--%3E%20C%0A%20%20%20%20C%20--%3E%20F%5BPoint%20gateway%20config%20at%20new%20credential%5D%0A%20%20%20%20F%20--%3E%20G%5BRolling%20restart%20of%20gateway%20replicas%5D%0A%20%20%20%20G%20--%3E%20H%7BHealth%20checks%20pass%3F%7D%0A%20%20%20%20H%20--%3E%7CNo%7C%20I%5BRoll%20back%20to%20previous%20credential%5D%0A%20%20%20%20I%20--%3E%20J%7BService%20recovered%3F%7D%0A%20%20%20%20J%20--%3E%7CNo%7C%20K%5BEscalate%20to%20on-call%20and%20open%20incident%5D%0A%20%20%20%20J%20--%3E%7CYes%7C%20L%5BFile%20post-incident%20ticket%5D%0A%20%20%20%20H%20--%3E%7CYes%7C%20M%5BVerify%20auth%20traffic%20end-to-end%5D%0A%20%20%20%20M%20--%3E%20N%5BRevoke%20old%20credential%5D%0A%20%20%20%20N%20--%3E%20O%5BRecord%20rotation%20in%20audit%20log%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h2 id="procedure" tabindex="-1">Procedure <a class="header-anchor" href="#procedure" aria-label="Permalink to &quot;Procedure&quot;">​</a></h2><ol><li><p><strong>Generate the new credential.</strong> In the secret manager, create a replacement credential for <code>gateway-auth-db</code> (role <code>gw_auth_reader_next</code>). Do not reuse the old password value.</p></li><li><p><strong>Grant access.</strong> Grant the new role the same read-only grants as the old role on the auth database.</p></li><li><p><strong>Point the gateway at the new credential.</strong> Update the gateway&#39;s config to reference the new secret path, and save the change.</p></li><li><p><strong>Rolling restart.</strong> Trigger a rolling restart of the gateway replicas so each replica reconnects with the new credential.</p></li><li><p><strong>Watch the rollout.</strong> Follow the rollout in the console (Figure 1) and confirm each replica reports <strong>Running</strong> before the next one is restarted.</p></li><li><p><strong>Verify.</strong> Complete the verification checklist below.</p></li><li><p><strong>Revoke the old credential.</strong> Once verification passes, revoke the old credential in the secret manager.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Revoking the old credential is the destructive step in this procedure. If any replica is still using the old credential, it loses access to the auth database and starts rejecting requests with <code>500</code> errors. Only revoke after every replica has been restarted with the new credential and the verification checklist passes.</p></div></li><li><p><strong>Record the rotation.</strong> Log the rotation (who, when, old and new credential IDs) in the audit log and close the pre-flight ticket.</p></li></ol><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><ul><li>[ ] All gateway replicas report <strong>Running</strong> in the console</li><li>[ ] Gateway health endpoint returns <code>200</code> on every replica</li><li>[ ] A test request with a valid API key returns <code>202 Accepted</code></li><li>[ ] A test request with an expired API key returns <code>401 Unauthorized</code></li><li>[ ] Gateway error rate is back to baseline within 15 minutes</li><li>[ ] No new <code>auth-db connection refused</code> log entries since the rollout</li></ul><h2 id="rollback" tabindex="-1">Rollback <a class="header-anchor" href="#rollback" aria-label="Permalink to &quot;Rollback&quot;">​</a></h2><p>If the gateway fails to come up with the new credential, or the error rate spikes during the rollout:</p><ol><li>Restore the previous config snapshot (step 3 in reverse) so the gateway references the old credential again.</li><li>Trigger a rolling restart of the gateway replicas.</li><li>Confirm the gateway is healthy and traffic is normal.</li><li>Leave the old credential active. Do not revoke it until the root cause is fixed and a fresh rotation succeeds.</li><li>File a ticket describing the failure, including the rollout logs and the time window of the error spike.</li></ol><p>If the old credential was already revoked (step 7) before the failure was noticed, the fastest recovery is to re-issue the old credential value from the secret manager&#39;s audit history, deploy it, and then investigate at lower urgency.</p>',8))])}const A=i(u,[["render",g]]);export{v as __pageData,A as default};
